    private static $catalog_cache=null;
    public static function init() {
        add_action('init',array(__CLASS__,'types'),9);
        add_action('rest_api_init',array(__CLASS__,'routes'));
        add_filter('pre_get_document_title',static function($title){if(function_exists('is_product')&&is_product()){$custom=get_post_meta(get_queried_object_id(),'_ge_seo_title',true);if($custom)return $custom;}return $title;});
