    }
    public static function types() {
        foreach(array(self::SOURCE,self::CHANGE) as $type) register_post_type($type,array('public'=>false,'show_ui'=>false,'supports'=>array('title')));
    }
    public static function enabled() { return GE_WTP_Operations::enabled() && get_option('ge_cost_engine_enabled')==='yes'; }
    public static function permission($write=false) {
        if(class_exists('GE_Organization_Runtime'))GE_Organization_Runtime::require_permission('cost_engine',$write);
        if(!self::enabled() || !is_user_logged_in() || (!current_user_can('manage_options')&&!current_user_can($write?'ge_manage_costs':'ge_view_costs'))) throw new RuntimeException('Sin permiso de costos.');
    }
    public static function install() {
        if(!current_user_can('manage_options')) throw new RuntimeException('Sólo un administrador puede instalar el módulo.');
        global $wpdb; $table=GE_WTP_Operations::table('recipes');
        if(!$wpdb->get_var($wpdb->prepare('SHOW COLUMNS FROM '.$table.' LIKE %s','cost_json'))) {
            if(false===$wpdb->query('ALTER TABLE '.$table.' ADD COLUMN cost_json longtext NULL')) throw new RuntimeException('No se pudo extender la receta existente.');
        }
        foreach(array('administrator',GE_WTP_Staff_Portal::ROLE) as $name) { $role=get_role($name); if($role) foreach(array('ge_view_costs','ge_manage_costs','ge_manage_products','upload_files') as $cap) $role->add_cap($cap); }
        update_option('ge_cost_engine_schema',self::VERSION,false);
    }
    public static function put($id,$key,$data) {
        update_post_meta($id,$key,wp_slash($data));
        $stored=get_post_meta($id,$key,true);
        // Global File Analyzer enriches the same workspace record synchronously.
        if($key===GE_WTP_Supplier_Workspace::META && is_array($stored) && is_array($data)){foreach(array('analysis','file_analysis_ref','analysis_status') as $field){unset($stored[$field],$data[$field]);}}
        if(is_array($data)?$stored!==$data:(string)$stored!==(string)$data) throw new RuntimeException('No se pudo guardar el registro.');
    }
    public static function audit($event,$ref,$before,$after) { GE_WTP_Operations::audit('cost_'.$event,$ref,array('before'=>$before,'after'=>$after)); }
    public static function hash($data) { return hash('sha256',wp_json_encode($data)); }
    public static function lock($key,$fn) {
        global $wpdb; $name='ge_cost_'.substr(hash('sha256',$key),0,40);
        if((int)$wpdb->get_var($wpdb->prepare('SELECT GET_LOCK(%s,5)',$name))!==1) throw new RuntimeException('Otra operación está en curso; reintentá.');
        try { return $fn(); } finally { $wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',$name)); }
    }
