        if($supplier) { $args['meta_key']='_ge_supplier_key'; $args['meta_value']=$supplier; }
        $out=array(); foreach(get_posts($args) as $id) { $r=get_post_meta($id,GE_WTP_Supplier_Workspace::META,true); if(($r['type']??'')!=='price_list') continue; $n=get_post_meta($id,self::LIST_META,true); $out[]=array('id'=>(int)$id,'supplier_id'=>get_post_meta($id,'_ge_supplier_key',true),'title'=>$r['title']??get_the_title($id),'effective_date'=>$r['valid_from']??'','uploaded_at'=>$r['created_at']??'','currency'=>strtoupper($r['currency']??'ARS'),'file_name'=>$r['file_name']??'','checksum'=>$r['file_hash']??'','status'=>$n['status']??(!empty($r['active'])?'legacy_active':'draft'),'active'=>!empty($r['active']),'notes'=>$r['notes']??'','count'=>count($n['items']??array())); }
        return $out;
    }
    public static function list_get($id) {
        self::permission(); $r=get_post_meta($id,GE_WTP_Supplier_Workspace::META,true); $supplier=get_post_meta($id,'_ge_supplier_key',true);
        if(get_post_type($id)!==GE_WTP_Supplier_Workspace::ENTRY || ($r['type']??'')!=='price_list' || !GE_WTP_Supplier_Workspace::supplier($supplier)) throw new RuntimeException('Lista inexistente.');
        return array('id'=>(int)$id,'supplier_id'=>$supplier,'workspace'=>$r,'normalized'=>get_post_meta($id,self::LIST_META,true)?:array('status'=>'draft','items'=>array()));
    }
    public static function normalize($items,$list) {
