            foreach((array)($row['attributes']??array()) as $key=>$value) $r['attributes'][sanitize_key($key)]=sanitize_text_field($value);
            $last=-1; foreach((array)($row['tiers']??array()) as $tier) { $q=GE_WTP_Cost_Math::number($tier['min_qty']??null,'escala',0); if($q<=$last) throw new InvalidArgumentException('Escalas deben ser únicas y ascendentes.'); $last=$q; $m=$tier['mode']??$mode; if(!in_array($m,array('unit','lot'),true)) throw new InvalidArgumentException('Modo de escala inválido.'); $r['tiers'][]=array('min_qty'=>$q,'cost'=>GE_WTP_Cost_Math::number($tier['cost']??null,'costo de escala'),'mode'=>$m); }
            $out[]=$r;
        }
        return $out;
    }
