        foreach($lines as $line){$source=self::source($line['source_ref']??'');$basis=$line['basis']??'output';if(!in_array($basis,array('output','job','sheet','area','meter','click','hours'),true))throw new RuntimeException('Base de receta inválida.');$units=array('sheet'=>'sheet','area'=>'m2','meter'=>'m','click'=>'click','hours'=>'hour');if(isset($units[$basis])&&$source['unit']!==$units[$basis])throw new RuntimeException('Unidad de receta distinta al insumo; agregá conversión explícita.');$group=$line['group']??'materials';if(!in_array($group,array('materials','process','supplier','labor','finishing','logistics','other'),true))throw new RuntimeException('Componente inválido.');$clean[]=array('source_ref'=>$source['ref'],'basis'=>$basis,'factor'=>GE_WTP_Cost_Math::number($line['factor']??1,'factor',0.000001),'outputs_per_sheet'=>GE_WTP_Cost_Math::number($line['outputs_per_sheet']??1,'rendimiento',0.000001),'group'=>$group,'waste'=>!empty($line['waste']),'optional_key'=>sanitize_key($line['optional_key']??''));}
        $defaults=$a['defaults']??array('currency'=>'ARS','quantity'=>1,'waste_percent'=>0);$rule=$a['price_rule']??array('mode'=>'markup','value'=>0);GE_WTP_Cost_Math::price(1,$rule);
        return GE_WTP_Operations::transaction(function()use($a,$name,$clean,$defaults,$rule){global $wpdb;$parent=absint($a['id']??0);if($parent)self::recipe($parent);$cost=array('lines'=>$clean,'defaults'=>$defaults,'price_rule'=>$rule,'actor_id'=>get_current_user_id(),'version_at'=>gmdate('c'));$legacy=$parent?self::recipe($parent)['lines_json']:'[]';if(false===$wpdb->insert(GE_WTP_Operations::table('recipes'),array('name'=>$name,'parent_id'=>$parent?:null,'lines_json'=>$legacy,'cost_json'=>wp_json_encode($cost),'updated_at'=>current_time('mysql',true))))throw new RuntimeException('No se pudo guardar receta.');$id=(int)$wpdb->insert_id;self::audit('recipe_version',$id,$parent?self::recipe($parent):null,$cost);return self::recipe($id);});
    }
    public static function calculate($a) {
        self::permission();$recipe=!empty($a['recipe_id'])?self::recipe(absint($a['recipe_id'])):null;$cost=$recipe['cost']??null;
        $input=array_merge($cost['defaults']??array(),$a['input']??array());$input+=array('quantity'=>1,'currency'=>'ARS','waste_percent'=>0,'faces'=>1);$qty=GE_WTP_Cost_Math::number($input['quantity'],'cantidad',0.000001,1000000);$waste=GE_WTP_Cost_Math::number($input['waste_percent'],'merma',0,1000);$lines=$cost['lines']??($a['lines']??array());$catalog=self::catalog();$sources=array_column($catalog,null,'ref');$parts=array();$missing=array();$groups=array_fill_keys(array('materials','process','supplier','labor','finishing','logistics','other','waste'),0);$total=0;
        if(!$lines&&$recipe){$estimate=GE_WTP_Operations_Equipment::recipe_estimate($recipe['id'],$qty,$input['faces'],(string)(1+$waste/100));foreach($estimate['lines'] as $r)$lines[]=array('source_ref'=>'stock/'.$r['material_id'].'/latest/'.$input['currency'],'basis'=>'job','factor'=>$r['quantity'],'group'=>'materials','waste'=>false);}
        if(!$lines||count($lines)>50)$missing[]='Faltan componentes de costo.';
        foreach($lines as $line){if(!empty($line['optional_key'])&&empty($input[$line['optional_key']]))continue;$ref=$line['source_ref']??'';$source=$sources[$ref]??null;$group=$line['group']??'materials';try{if(!$source)throw new RuntimeException('Fuente no disponible.');if(!isset($groups[$group])||$group==='waste')throw new RuntimeException('Componente inválido.');$units=array('sheet'=>'sheet','area'=>'m2','meter'=>'m','click'=>'click','hours'=>'hour');$basis=$line['basis']??'output';if(isset($units[$basis])&&$source['unit']!==$units[$basis])throw new RuntimeException('La base de cálculo no coincide con la unidad del costo.');$base=GE_WTP_Cost_Math::quantity($line,$input);$amount=GE_WTP_Cost_Math::line($source,$base,$input);$extra=!empty($line['waste'])?$amount*$waste/100:0;$total+=$amount+$extra;$groups[$group]+=$amount;$groups['waste']+=$extra;$parts[]=array('source'=>$source,'quantity'=>$base,'group'=>$group,'subtotal'=>$amount,'waste'=>round($extra,4));}catch(Throwable $e){$missing[]=$ref.': '.$e->getMessage();}}
        if(!$parts)$missing[]='No hay componentes activos para este cálculo.';if(!is_finite($total)||$total>1000000000000)throw new RuntimeException('Costo calculado fuera de rango.');
        $rule=$a['price_rule']??($cost['price_rule']??array('mode'=>'markup','value'=>0));$price=GE_WTP_Cost_Math::price($total,$rule);$complete=!$missing;
        return array('recipe_id'=>$recipe?(int)$recipe['id']:null,'recipe_hash'=>$recipe?self::hash($recipe):null,'input'=>$input,'components'=>$parts,'breakdown'=>$groups,'total_cost'=>round($total,4),'unit_cost'=>round($total/$qty,4),'currency'=>$input['currency'],'complete'=>$complete,'missing'=>$missing,'pricing'=>$complete?$price:null,'calculated_at'=>gmdate('c'),'fingerprint'=>self::hash(array($recipe,$input,$lines,$rule,$parts)));
    }
    public static function quote_snapshot($a){
        self::permission(true);$calculation=self::calculate($a['calculation']??array());if(!$calculation['complete']||$calculation['currency']!=='ARS')throw new RuntimeException('El presupuesto requiere costo completo en ARS.');
