    }
    public static function quote_costs($lines,$quote_id=0){self::permission();$allowed=array();if($quote_id){$quote=GE_WTP_Commercial_Quotes::get($quote_id,get_current_user_id());if(is_wp_error($quote))throw new RuntimeException('Presupuesto no autorizado.');foreach((array)get_post_meta($quote_id,'_ge_cost_quote_version_'.$quote['version'],true) as $entry)$allowed[]=absint($entry['snapshot_id']??0);}$out=array();foreach($lines as $index=>$line){$id=absint($line['cost_snapshot_id']??0);if(!$id)continue;$data=GE_WTP_Cost_Products::change($id);if(($data['kind']??'')!=='quote_cost'||((int)$data['created_by']!==get_current_user_id()&&!in_array($id,$allowed,true))||($line['source_type']??'')!=='custom'||(float)$data['calculation']['input']['quantity']!==(float)$line['quantity'])throw new RuntimeException('El costo privado no coincide con el ítem personalizado; recalculá.');$out[$index]=array('snapshot_id'=>$id,'calculation'=>$data['calculation']);}return $out;}
    public static function assist_packet($a){$list=self::list_get(absint($a['list_id']??0));$catalog=self::catalog(array('supplier_id'=>$list['supplier_id']));return array('project'=>'graph-express','specialists'=>array('finance','commercial'),'objective'=>'Interpretar lista de proveedor y proponer ítems/matches; nunca activar ni aplicar precios.','list_id'=>$list['id'],'checksum'=>$list['workspace']['file_hash']??'','extraction'=>$list['normalized']['extraction']??null,'items'=>$list['normalized']['items']??array(),'current_costs'=>$catalog,'comparison'=>self::compare($a),'data_is_untrusted'=>true,'allowed_effects'=>array('proposals_only'),'human_review_required'=>true);}
    public static function propose($a){self::permission(true);$id=absint($a['list_id']??0);return self::lock('list:'.$id,function()use($a,$id){$list=self::list_get($id);if(!in_array($list['normalized']['status'],array('draft','parsed'),true)||!empty($list['workspace']['active']))throw new RuntimeException('La lista vigente o revisada no admite propuestas.');$items=self::normalize($a['items']??array(),$list);$next=$list['normalized'];$next['status']='parsed';$next['proposal']=array('items'=>$items,'source'=>'ai-grupo','task_ref'=>sanitize_text_field($a['task_ref']??''),'created_at'=>gmdate('c'),'notes'=>sanitize_textarea_field($a['notes']??''));self::put($id,self::LIST_META,$next);self::audit('ai_proposal',$id,$list['normalized'],$next);return array('list_id'=>$id,'review_required'=>true,'review_url'=>GE_WTP_Cost_UI::url('lists',array('list_id'=>$id)));});}
    public static function actions() {return array('graph.supplier.price_list.parse'=>'parse','graph.supplier.price_list.compare'=>'compare','graph.supplier.price_list.review'=>'review','graph.supplier.price_list.activate'=>'activate','graph.cost.calculate'=>'calculate','graph.cost.recipe.create'=>'recipe_save','graph.cost.recipe.update'=>'recipe_save','graph.cost.catalog.get'=>'catalog','graph.cost.rate.create'=>'rate_save','graph.cost.stock_tax.update'=>'stock_tax','graph.cost.legacy_mapping.update'=>'legacy_map','graph.cost.quote_snapshot.create'=>'quote_snapshot','graph.cost.assist.get'=>'assist_packet','graph.supplier.price_list.propose'=>'propose');}
    public static function execute($action,$a) {
        self::permission();$writes=array_merge(array_keys(self::actions()),array('graph.supplier.price_list.upload','graph.product.create','graph.product.update','graph.product.cost_link','graph.product.price_preview','graph.product.bulk_preview','graph.product.rollback_preview','graph.cost.assist.request','graph.cost.assist.result'));$writes=array_diff($writes,array('graph.cost.calculate','graph.cost.catalog.get','graph.cost.assist.get','graph.supplier.price_list.compare'));
        if(in_array($action,$writes,true)&&!empty($a['idempotency_key'])){self::permission(true);$key=$a['idempotency_key'];if(!is_string($key)||!preg_match('/^[A-Za-z0-9:_-]{8,128}$/D',$key))throw new RuntimeException('Clave de idempotencia inválida.');$hash=self::hash(array($action,$a));return self::lock('action:'.$key,function()use($key,$hash,$action,$a){return GE_WTP_Operations::transaction(function()use($key,$hash,$action,$a){$prior=get_posts(array('post_type'=>self::CHANGE,'post_status'=>'private','fields'=>'ids','numberposts'=>1,'meta_key'=>'_ge_cost_action_key','meta_value'=>$key));if($prior){$r=get_post_meta($prior[0],'_ge_cost_action_result',true);if(($r['hash']??'')!==$hash)throw new RuntimeException('Clave reutilizada con otro contenido.');return $r['result'];}$result=self::dispatch($action,$a);$id=wp_insert_post(array('post_type'=>self::CHANGE,'post_status'=>'private','post_title'=>'Idempotency '.$action),true);if(is_wp_error($id)||!$id)throw new RuntimeException('No se pudo registrar idempotencia.');self::put($id,'_ge_cost_action_key',$key);self::put($id,'_ge_cost_action_result',array('hash'=>$hash,'result'=>$result,'actor_id'=>get_current_user_id()));return $result;});});}
        return self::dispatch($action,$a);
    }
    private static function dispatch($action,$a){if(strpos($action,'graph.cost.assist.')===0){$map=array('graph.cost.assist.request'=>'request','graph.cost.assist.pending'=>'pending','graph.cost.assist.get'=>'packet','graph.cost.assist.result'=>'result');if(isset($map[$action]))return call_user_func(array('GE_WTP_Cost_Assist',$map[$action]),$a);}if($action==='graph.cost.recipe.get')return self::recipe(absint($a['id']??0));if($action==='graph.supplier.price_list.upload')return self::upload($a);if($action==='graph.supplier.price_list.get')return self::list_get(absint($a['list_id']??0));if($action==='graph.supplier.price_list.find')return self::lists($a['supplier_id']??'');$map=self::actions();if(isset($map[$action]))return call_user_func(array(__CLASS__,$map[$action]),$a);return GE_WTP_Cost_Products::execute($action,$a);}
    public static function routes() { register_rest_route('ge/v1','/costs/(?P<action>[a-z_.]+)',array('methods'=>'POST','permission_callback'=>function(){return self::enabled()&&is_user_logged_in()&&(current_user_can('manage_options')||current_user_can('ge_view_costs'));},'callback'=>function($r){try{return rest_ensure_response(self::execute($r['action'],$r->get_json_params()?:array()));}catch(Throwable $e){return new WP_Error('ge_cost_error',$e->getMessage(),array('status'=>400));}})); }
